const N = 20;
const totals = [];
for (let falseCount = 0; falseCount <= N; falseCount++) {
  const trueClaims = [];
  for (let k = 1; k <= N; k++) {
    if (falseCount >= k) trueClaims.push(k);
  }
  if (N - trueClaims.length === falseCount) {
    totals.push(trueClaims.reduce((sum, k) => sum + k, 0));
  }
}
return totals.length === 1 ? totals[0] : NaN;
